-- Directory — Vegas parity backfill (ADR-13 #4, Phase 3A part B). Generated by scripts/gen-vegas-parity.mjs.
-- One draft facility_listings row per Las Vegas locations row (64; "AAA Test" excluded), batch-tagged
-- source='vegas-parity-2026-07' (rollback = delete by source), provenance origin='locations'. access_type mapped to the
-- unified vocab + fee_type/indoor per the gate decision. Rows stay DRAFT (no name_source_url/verified_at) —
-- Vegas Verify/Enrich publishes them later; the publish gate is untouched. Insert + link run in one transaction.


-- link each operational location to its new directory record (same transaction as the insert)
update public.locations l
  set facility_listing_id = fl.id
  from public.facility_listings fl
  where fl.source = 'vegas-parity-2026-07' and (fl.provenance->>'location_id')::uuid = l.id;
